boolean <mask>(int shard, int segment) {
    if (lastShard == shard) {
        if (lastSegment == segment) {
            return false;
        }
        lastSegment = segment;
        for (FieldWork w : fields) {
            w.sameShardNewSegment();
        }
        return true;
    }
    lastShard = shard;
    lastSegment = segment;
    for (FieldWork w : fields) {
        w.newShard(shard);
    }
    return true;
}

