static void <mask>(double[] a, int k, int n) {
    while (2*k <= n) {
        int j = 2 * k;
        if (j < n && a[j] < a[j + 1]) {
            j++;
        }
        if (a[k] >= a[j]) {
            break;
        }
        swap(a, k, j);
        k = j;
    }
}

