private static <T extends Comparable<T>> void <mask>(T[] array, final int low, final int high) {
    for (int i = low + 1; i <= high; i++) {
        final T key = array[i];
        int j = i - 1;
        while (j >= low && SortUtils.greater(array[j], key)) {
            array[j + 1] = array[j];
            j--;
        }
        array[j + 1] = key;
    }
}

