public int <mask>(int startPosition, char c) {

    int readPosition = startPosition + 1;
    boolean inEscape = false;
    while (!isOutOfBounds(readPosition)) {
        if(inEscape){
            inEscape = false;
        } else if('\\' == charAt(readPosition)){
            inEscape = true;
        } else if (c == charAt(readPosition)){
            return readPosition;
        }
        readPosition ++;
    }
    return -1;
}

