private int <mask>(Group[] groups) {
    int g = groups.length - 1;
    Group group = groups[g];
    bytes.setLength(group.bytesStart);
    while (group.writtenValues == group.valueCount) {
        group.writtenValues = 0;
        if (g == 0) {
            return -1;
        } else {
            group = groups[--g];
            bytes.setLength(group.bytesStart);
        }
    }
    return g;
}

