@Override
public double <mask>(double k) {
    int L = Math.max(0, m + n - N);
    if (k < L) {
        return 0.0;
    } else if (k >= Math.min(m, n)) {
        return 1.0;
    }

    double p = 0.0;
    for (int i = L; i <= k; i++) {
        p += p(i);
    }

    return p;
