@Override
public int <mask>(byte[] b, int off, int len) throws IOException {
    int remaining = len;
    int read = 0;
    while (remaining > 0) {
        final int r = doRead(b, off + read, remaining);
        if (r <= 0) {
            break;
        }
        read += r;
        remaining -= r;
    }
    if (len > 0 && remaining == len) {

        return -1;
    }
    return read;
}

