    while (currentTokenIndex < bytes.length) {
        currentNode = currentNode.children.computeIfAbsent(fromBytesRef(bytes, currentTokenIndex), k -> new BytesTrie());
        currentTokenIndex++;
    }
    currentNode.setLeaf(true);
}

