private <T extends Comparable<T>> boolean <mask>(final T[] arr, final int gap) {
    boolean swapped = false;

    for (int i = 0; i < arr.length - gap; i++) {
        if (SortUtils.less(arr[i + gap], arr[i])) {
            SortUtils.swap(arr, i, i + gap);
            swapped = true;
        }
    }

    return swapped;
}

