private static String <mask>(StyleData style) {
  if (style == null) {
    return null;
  }
  String parent = style.getParent();
  if (parent == null || parent.isEmpty()) {
    parent = null;
    String name = style.getName();
    if (name.contains(".")) {
      parent = name.substring(0, name.lastIndexOf('.'));
      if (parent.isEmpty()) {
        return null;
      }
    }
  }
  return parent;
}

